const workerTransforms=root=>new Map([...root.querySelectorAll('[data-worker],[data-forklift],[data-glide]')].map(el=>[el.dataset.worker??el.dataset.forklift??el.dataset.glide,el.getAttribute('transform')]));
// A live panel of a HOME / YARD render: its HTML is remembered so a poll can rebuild only the panels whose HTML changed. sel null = no element of its own (any change rebuilds the page).
