const homeHero=()=>'<div class="home-hero"><div class="hero-art">'+HERO_ART+'</div><div class="hero-top"><div class="hero-title"><div class="eyebrow">SCAFFOLD / HOME &middot; '+esc(account.company?.name??'')+'</div><h1>'+esc(state.yards[0].name)+'</h1><p class="hero-sub">Your yard. Run it from here.</p></div><div class="hero-actions">'+part('live','.home-hero .hero-live',heroLive)+part('pause','#pause',pauseButton)+'</div></div>'+part('hud','.home-hero .hud-stats',hudStats)+'<div class="simulation-banner"><span class="status-dot"></span> SIMULATION / DEMONSTRATION <span>Not real lifting operations or certified load engineering.</span></div></div>';
