const trkBand=(title,sub,art,stats,label)=>'<div class="tk-band page-hero"><div class="tk-band-top">'+heroEyebrow()+'<h1>'+title+'</h1><p class="hero-sub">'+sub+'</p>'+heroActions()+'</div><div class="tk-band-art" aria-hidden="true">'+art+'</div><div class="tk-hud" role="list" aria-label="'+label+'">'+stats+'</div>'+heroBanner()+'</div>';
const trkScene=heavy=>trkScenePic(heavy?'heavy':'light','<path d="M-10 138 214 30 450 128 226 236Z" fill="#8fa866"/><path d="M-10 170 330 6h70L-10 196Z" fill="#55595b" opacity=".92"/><path d="M26 164 346 10" stroke="#e8e3cf" stroke-width="2.4" stroke-dasharray="14 12" opacity=".7"/><path d="M96 142 244 72 400 130 252 200Z" fill="#d8d1c1"/><path d="M96 142 252 200 400 130v6L252 206 96 148Z" fill="#a79f8b"/><path d="M150 130 262 78M200 154 312 102M250 176 362 124" stroke="#e3bd2c" stroke-width="2" opacity=".85"/>'+
 '<use href="#spr-tree" x="376" y="40" width="54" height="64"/><use href="#spr-tree" x="12" y="96" width="46" height="54"/>'+(heavy?'<use href="#spr-truck12" x="176" y="42" width="200" height="106"/>':'<use href="#spr-truck2" x="196" y="54" width="160" height="90"/>')+'<use href="#spr-stillage" x="110" y="112" width="62" height="41"/><use href="#spr-stillage" x="110" y="88" width="62" height="41"/><use href="#spr-forklift-load" x="152" y="118" width="80" height="62"/><use href="#spr-worker" x="298" y="134" width="22" height="41"/>');
const trkWhere=t=>t.status==='IN_TRANSIT'?['road','On the road']:t.status==='AT_SITE'?['site','At site']:['yard','At the yard'];
// What the truck is doing, in the truck-stage words the Overview and Home use, as a pill in the crew-card colours.
const trkDoing=t=>{if(t.status==='IN_TRANSIT')return t.deckArea>0?['drive','Delivering a load']:['walk','Travelling empty'];const s=truckStage(t,state);return s==='UNLOADING'?['load','Unloading']:s==='LOADING'?(t.tasksTo>0?['load','Loading']:['job','Loaded, ready to go']):s==='SCHEDULED'?['job','Booked for a load']:['idle','Free for the next run'];};
const trkPct=(a,b)=>a==null||!b?0:Math.max(0,Math.min(100,a*100/b));
function trkHero(heavy,trucks){const road=trucks.filter(t=>t.status==='IN_TRANSIT'),yard=trucks.filter(t=>t.status==='AT_YARD').length,site=trucks.filter(t=>t.status==='AT_SITE').length,cap=trucks.reduce((s,t)=>s+t.payload,0),known=trucks.every(t=>t.loadedWeight!=null),on=trucks.reduce((s,t)=>s+(t.loadedWeight??0),0),ids=new Set(trucks.map(t=>t.id)),loads=state.tasks.filter(x=>ids.has(x.to)).length,unloads=state.tasks.filter(x=>ids.has(x.from)).length,art=heavy?'spr-truck12':'spr-truck2';
 const dest=[...new Set(road.map(t=>name(t.destination)))];
 return trkBand('Truck garage',trucks.length?(trucks.length===1?'1 truck':trucks.length+' trucks')+' &middot; '+(heavy?'6 m deck, 12,500 kg payload':'4.2 m deck, 2,000 kg payload')+' as standard':'No trucks in this class yet.',trkScene(heavy),
  trkStat(art,'At the yard',num(yard)+'<small>/ '+num(trucks.length)+'</small>',site?site+' at '+(site===1?'a site':'sites'):'None at sites',trkPct(yard,trucks.length))+trkStat(art,'On the road',num(road.length),road.length?'To '+esc(dest.join(', ')):'Nobody travelling')+trkStat('spr-stillage','On board',known?kg(on).replace(' kg','<small>kg</small>'):'Unknown',dual('of '+kg(cap)+' payload','/ '+kg(cap)),trkPct(on,cap))+trkStat(loads||unloads?'spr-forklift-load':'spr-forklift','Forklift work',num(loads+unloads),loads||unloads?dual([loads&&loads+' loading',unloads&&unloads+' unloading'].filter(Boolean).join(' &middot; '),[loads&&loads+' load',unloads&&unloads+' unload'].filter(Boolean).join(' &middot; ')):'All quiet'),'Trucks at a glance');}
// Payload: loaded and reserved as two segments of one bar; deck: the share of the ground deck covered.
function trkGauges(t){const known=t.loadedWeight!=null&&t.reservedWeight!=null,free=known?t.payload-t.loadedWeight-t.reservedWeight:null,deck=t.length*t.width?100*t.deckArea/(t.length*t.width):0,load=state.containers.filter(c=>c.location===t.id),ground=load.filter(c=>!c.support).length,over=known&&free<0;
 return '<div class="trk-gauge'+(over?' over':'')+'"><div class="trk-g-head"><span>Payload</span><b>'+kg(t.loadedWeight)+'<small>/ '+kg(t.payload)+'</small></b></div><i class="trk-bar" aria-hidden="true"><b data-style="width:'+trkPct(t.loadedWeight,t.payload)+'%"></b><em data-style="width:'+trkPct(t.reservedWeight,t.payload)+'%"></em></i><div class="trk-g-foot"><span><i class="k-load"></i>Loaded '+kg(t.loadedWeight)+'</span><span><i class="k-res"></i>Reserved '+kg(t.reservedWeight)+'</span><span class="trk-free">'+(known?(over?'Over by '+kg(-free):kg(free)+' free'):'Remaining unknown')+'</span></div></div>'+
  '<div class="trk-gauge deck"><div class="trk-g-head"><span>Deck area</span><b>'+deck.toFixed(1)+'%<small>of the ground deck</small></b></div><i class="trk-bar" aria-hidden="true"><b data-style="width:'+Math.min(100,deck)+'%"></b></i><div class="trk-g-foot"><span>'+(load.length?load.length+(load.length===1?' stillage':' stillages')+(load.length>ground?' &middot; '+(load.length-ground)+' stacked':''):'Empty deck')+'</span><span class="trk-free">'+(t.length/1000)+' &times; '+(t.width/1000)+' m</span></div></div>';}
// Where it is and where it goes: a small route strip with the truck on it (parked at the start, half way while travelling).
