function truckView(match=()=>true){const heavy=view!=='TRUCK2';const trucks=state.trucks.filter(match);return '<div class="page-trucks">'+trkHero(heavy,trucks)+(!trucks.length?emptyState('TRUCKS',heavy?'No 12.5 tonne trucks yet.':'No 2 tonne trucks yet.','Add one below or with the +1 button on the Equipment page.'):'')+trucks.map(trkGarage).join('')+(account.permissions.includes('operations.manage')?'<div class="trk-add">'+form('truck',trkPic(heavy?'spr-truck12':'spr-truck2','trk-add-art')+'<span>'+(heavy?'Add a 12.5 tonne truck':'Add a 2 tonne truck')+'</span>',text('name','Truck name',`${heavy?'T':'L'}-${String(trucks.length+1).padStart(2,'0')}`)+select('yard','Home yard',state.yards)+number('length','Deck length (mm)',heavy?6000:4200,1)+number('width','Deck width (mm)',heavy?2100:1900,1)+number('payload','Payload (g)',heavy?12500000:2000000,1),'Add truck')+'</div>':'')+'</div>';}
