// A chip with a line glyph; links for email and phone.
const siChip=(g,html,cls='')=>'<span class="si-chip'+(cls?' '+cls:'')+'">'+siGlyph(g)+'<span>'+html+'</span></span>';
function siKeys(s,boxes,pieces,trucks,crew){const cranes=crew.filter(r=>r.type==='CRANE').length,workers=crew.filter(r=>r.type==='WORKER').length,cages=boxes.filter(c=>c.type==='CAGE').length;const k=(art,v,l)=>'<div class="si-key"><span class="si-key-art">'+art+'</span><span><b>'+v+'</b><small>'+l+'</small></span></div>';
 return '<div class="si-keys" role="list" aria-label="'+esc(s.name)+' at a glance">'+k(siImg('spr-bundle'),num(pieces),'pieces on site')+k(siImg(cages&&cages===boxes.length?'spr-cage':'spr-stillage'),num(boxes.length),boxes.length===1?(cages?'cage':'stillage'):cages?'stillages &amp; cages':'stillages')+k(siImg('spr-truck12'),num(trucks.length),trucks.length===1?'truck here':'trucks here')+k(cranes?siImg('si-crane'):siImg('spr-worker'),workers+(cranes?'<small class="si-plus">+'+cranes+'</small>':''),cranes?(workers===1?'worker':'workers')+' &middot; '+(cranes===1?'crane':cranes+' cranes'):'site crew')+'</div>';}
// Stillages and cages on the site as compact sprite tiles (same select / drag behaviour as the container cards).
function siTiles(id,boxes,ix){const drag=isOps()?'true':'false';if(!boxes.length)return '<p class="si-none">'+siImg('spr-stillage')+'<span>No stillages or cages here yet.</span></p>';return '<div class="si-tiles" data-keep-scroll="si-tiles-'+id+'">'+boxes.map(c=>{const pcs=ix.pcs.get(c.id)??0,lines=ix.lines.get(c.id)??[],good=c.condition==='SERVICEABLE',what=lines.map(l=>l.quantity+' × '+(ix.pname.get(l.product_id)??name(l.product_id)));return '<button type="button" class="si-tile'+(c.id===selected?' is-selected':'')+(good?'':' attention')+'" data-select="'+c.id+'" draggable="'+drag+'" title="'+esc(c.name+' · '+c.type+(what.length?' · '+what.join(', '):' · empty')+(good?'':' · '+c.condition))+'"><span class="si-tile-art">'+siImg(c.type==='CAGE'?'spr-cage':'spr-stillage')+(pcs?'<b class="si-tile-pcs">'+num(pcs)+'</b>':'')+'</span><span class="si-tag">'+esc(c.name)+'</span><small class="si-tile-what">'+(lines.length?esc(ix.pname.get(lines[0].product_id)??name(lines[0].product_id)).replace(/(\d) (?=(?:mm|m|kg|t)\b)/g,'$1&nbsp;')+(lines.length>1?' <em>+'+(lines.length-1)+' more</em>':''):'Empty')+'</small>'+(good?'':'<small class="si-flag-bad">'+esc(c.condition)+'</small>')+(c.support?'<small class="si-stacked">stacked</small>':'')+'</button>';}).join('')+'</div>';}
// A truck parked at the site: a drop target (drop a stillage to load it for return) with its remove button; trucks on the way are shown without the drop.
function siTruck(t,coming=false){const ops=isOps(),heavy=t.payload>=10000000,load=state.containers.filter(c=>c.location===t.id).length;return '<div class="si-truck'+(coming?' coming':ops?' drop-zone':'')+(ops?'':' view-only')+'"'+(coming||!ops?'':' data-drop="'+t.id+'"')+'><span class="si-truck-art">'+siImg(heavy?'spr-truck12':'spr-truck2')+'</span><span class="si-truck-text"><span class="si-truck-name"><span class="si-tag">'+esc(t.name)+'</span><span class="si-pill '+(coming?'road':'live')+'">'+(coming?'On the way':'At this site')+'</span></span><small>'+(heavy?'12.5 t':'2 t')+' &middot; '+(load?load+(load===1?' stillage':' stillages')+' on deck'+(t.loadedWeight?' &middot; '+kg(t.loadedWeight):''):'deck empty')+'</small>'+(coming||!ops?'':'<span class="si-drop-hint">'+siGlyph('drop')+'Drop a stillage or cage here to load it for return</span>')+'</span>'+(coming?'':truckRemoveButton(t))+'</div>';}
function siCard(s,ix){const ops=isOps(),live=s.status==='ACTIVE',boxes=ix.byLoc.get(s.id)??[],pieces=boxes.reduce((n,c)=>n+(ix.pcs.get(c.id)??0),0),trucks=state.trucks.filter(t=>t.at===s.id&&t.status==='AT_SITE'),coming=state.trucks.filter(t=>t.status==='IN_TRANSIT'&&t.destination===s.id),crew=state.resources.filter(r=>r.location===s.id),moves=state.tasks.filter(t=>t.handling===s.id).length,dockets=state.deliveries.filter(d=>d.to===s.id&&d.manifest?.length).slice(-5).reverse();
 const contact=[s.contact?esc(s.contact):'',s.phone?'<a href="tel:'+esc(s.phone.replace(/[^+\d]/g,''))+'">'+esc(s.phone)+'</a>':'',s.email?'<a href="mailto:'+esc(s.email)+'">'+esc(s.email)+'</a>':''].filter(Boolean).join(' &middot; ');
 const chips=siChip('pin',esc(s.address||'No address yet'))+(s.client?siChip('client',esc(s.client),'client'):'')+(contact?siChip('person',contact):'')+siChip('hat',s.supervisorName?'Supervisor <b>'+esc(s.supervisorName)+'</b>':'No supervisor assigned',s.supervisorName?'sup':'sup none')+(s.lastDeliveryAt?siChip('clock','Last delivery '+siAgo(s.lastDeliveryAt)):'');
 const pills='<span class="si-pill '+(live?'live':'off')+'">'+(live?'Active':esc(s.status.charAt(0)+s.status.slice(1).toLowerCase()))+'</span>'+(coming.length?'<span class="si-pill road">'+(coming.length===1?'Truck on the way':coming.length+' trucks on the way')+'</span>':'')+(moves?'<span class="si-pill work">'+(moves===1?'1 move':moves+' moves')+' on site</span>':'');
 const parked=trucks.length?'<div class="si-parked">'+trucks.slice(0,2).map(t=>'<span class="si-parked-truck">'+siImg(t.payload>=10000000?'spr-truck12':'spr-truck2')+'<span class="si-tag">'+esc(t.name)+'</span></span>').join('')+'<small>'+(trucks.length===1?'parked on site':trucks.length+' trucks parked')+'</small></div>':'';
 const edit=ops&&live?form('site-details-'+s.id,'<span class="si-form-title">'+siGlyph('client')+'<span>Edit site details<small>Name, address, client, contact and supervisor</small></span></span>',text('name','Site name',s.name)+text('address','Address / location',s.address)+'<label>Client company<input name="client" maxlength="250" value="'+esc(s.client??'')+'"></label><label>Site contact<input name="contact" maxlength="250" value="'+esc(s.contact??'')+'"></label><label>Contact email<input name="email" type="email" maxlength="254" value="'+esc(s.email??'')+'"></label><label>Contact phone<input name="phone" maxlength="60" value="'+esc(s.phone??'')+'"></label>'+(account.users.length?'<label>Assigned supervisor<select name="supervisor"><option value="">Not assigned</option>'+options(account.users,'name',s.supervisor)+'</select></label>':'<p class="muted">Supervisor: '+esc(s.supervisorName??'Not assigned')+'</p>'),'Save site details'):'';
 const actions=ops&&(live||s.status!=='ARCHIVED')?'<div class="si-actions">'+(live?'<button type="button" class="secondary si-shape" data-edit-site="'+s.id+'">Change site shape &amp; size</button>':'')+(s.status!=='ARCHIVED'?'<button class="secondary si-archive" data-archive="'+s.id+'">Archive empty site</button>':'')+'</div>':'';
 return '<section class="panel si-card'+(live?'':' is-off')+'" data-site-panel="'+s.id+'" id="si-site-'+s.id+'"><div class="si-head"><span class="si-badge">'+siImg('si-site')+'</span><div class="si-title"><div class="si-name-row"><h2>'+esc(s.name)+'</h2>'+pills+'</div><div class="si-chips">'+chips+'</div></div>'+siKeys(s,boxes,pieces,trucks,crew)+'</div>'
 +'<div class="si-body"><div class="si-plan"><div class="si-plan-frame">'+planWrap(s,yardSVG(s,state.containers,state.tasks,selected,[],state.resources,null,planOpts({view:siteViewOf()})))+'<span class="si-plan-size">'+siGlyph('size')+dims(s)+'<span class="si-plan-h"> &middot; height '+((s.height??10000)/1000).toFixed(1)+' m</span></span>'+parked+'</div>'+selectionBar(s)+'</div>'
 +'<div class="si-side"><div class="si-block"><h3 class="si-sub">On site <span class="si-count">'+boxes.length+'</span></h3>'+siTiles(s.id,boxes,ix)+'</div><div class="si-block"><h3 class="si-sub">Trucks here <span class="si-count">'+trucks.length+'</span></h3>'+(trucks.length||coming.length?'<div class="drop-zones si-trucks">'+trucks.map(t=>siTruck(t)).join('')+coming.map(t=>siTruck(t,true)).join('')+'</div>':'<p class="si-none">'+siImg('spr-truck12')+'<span>'+(ops?'No truck on site. Send one from a truck page.':'No truck on site right now.')+'</span></p>')+'</div></div></div>'
 +actions+edit+(dockets.length?'<div class="si-dockets"><h3 class="si-sub">'+siImg('si-docket','si-sub-art')+'Delivery dockets <span class="si-count">'+dockets.length+'</span></h3>'+dockets.map(d=>manifestPanel(d,'Delivery docket')).join('')+'</div>':'')+'</section>';}
function siteView(){if(editing('site'))return shapeHost();siMount();const ix=siIndex(),ops=isOps();return '<div class="page-sites">'+siHero(ix)+(!state.sites.length?'<section class="panel si-empty">'+siImg('si-site','si-empty-art')+'<h2>'+(ops?'Ready for your next site.':'No sites assigned to you yet.')+'</h2><p>'+(ops?'Create a site to track deliveries, returns and stock.':'The office assigns sites to supervisors; yours will show here with its stock and trucks.')+'</p></section>':'')+state.sites.map(s=>siCard(s,ix)).join('')+(ops?'<div class="si-new">'+form('site','<span class="si-form-title">'+siImg('si-site','si-form-art')+'<span>Create a site<small>Name, address, client and contact; draw its shape after</small></span></span>',text('name','Site name')+text('address','Address / location')+'<label>Client company (optional)<input name="client" maxlength="250"></label><label>Site contact (optional)<input name="contact" maxlength="250"></label><label>Contact email (optional)<input name="email" type="email" maxlength="254"></label><label>Contact phone (optional)<input name="phone" maxlength="60"></label>'+`<label>Assigned supervisor<select name="supervisor"><option value="">Not assigned</option>${options(account.users)}</select></label>`,'Create site')+'</div>':'')+'</div>';}
function requestView(){siMount();const all=state.loadLists??[],open=all.filter(l=>!l.cancelled&&l.status!=='DELIVERED'),waiting=open.filter(l=>l.status==='OPEN'&&!l.truck).length,done=all.length-open.length,single=state.requests.filter(r=>!r.loadList),empty=!state.requests.length&&!all.length,listForm=loadListForm();
 const counts=all.length||single.length?'<div class="si-list-counts"><span class="si-pill '+(open.length?'work':'idle')+'">'+open.length+' open</span>'+(waiting?'<span class="si-pill road">'+waiting+' waiting for a truck</span>':'')+(done?'<span class="si-pill idle">'+done+' done or cancelled</span>':'')+(single.length?'<span class="si-pill idle">'+single.length+(single.length===1?' single request':' single requests')+'</span>':'')+'</div>':'';
 return '<div class="page-sites"><section class="si-lists"><div class="si-section-head">'+siImg('si-docket','si-section-art')+'<div><h2>Yard lists &amp; requests</h2><p>What each site needs from the yard. A yard list reserves exact packs, loads one truck and travels with it as the delivery docket.</p></div>'+counts+'</div>'
 +(empty?'<div class="si-lists-empty">'+'<div class="si-steps"><div class="si-step"><span class="si-step-art">'+siImg('si-docket')+'</span><b>1</b><span>List the materials for a site</span></div><i class="si-step-arrow" aria-hidden="true"></i><div class="si-step"><span class="si-step-art">'+siImg('spr-forklift-load')+'</span><b>2</b><span>The yard reserves packs and loads the truck</span></div><i class="si-step-arrow" aria-hidden="true"></i><div class="si-step"><span class="si-step-art">'+siImg('spr-truck12')+'</span><b>3</b><span>The list travels as the delivery docket</span></div></div><h3>Every delivery starts with a yard list.</h3><p>'+(listForm?'Create one below: pick the site, then the products and quantities.':'Create a site and turn on a product system to start one.')+'</p></div>':'')
 +yardListsPanel(l=>!l.cancelled&&l.status!=='DELIVERED',true)+yardListsPanel(l=>l.cancelled||l.status==='DELIVERED',true)
 +state.requests.filter(r=>!r.loadList).map(r=>`<section class="panel si-request"><div class="row"><h2>${esc(name(r.site))}</h2><span class="badge">${esc(r.status)}</span></div><p><strong>${r.quantity} × ${esc(name(r.product))}</strong></p><p>Allocated: ${r.allocated} · Placed at site: ${r.delivered} · Exact quantity only.</p>${r.status==='REQUESTED'&&account.permissions.includes('operations.manage')?`<form data-allocate="${r.id}">${select('truck','Loading truck',state.trucks.filter(t=>t.status==='AT_YARD'))}<button>Plan packs & load truck</button></form>`:''}${['REQUESTED','ALLOCATED','PARTIALLY ALLOCATED'].includes(r.status)&&account.permissions.includes('requests.create')?`<div class="actions"><button type="button" class="secondary" data-cancel-request="${r.id}">Cancel request</button></div>`:''}</section>`).join('')
 +'<div class="si-form-row">'+listForm+form('request','<span class="si-form-title">'+siImg('spr-bundle','si-form-art')+'<span>Quick single-line request<small>One product to one site, exact quantity</small></span></span>',select('site','Destination site',state.sites.filter(s=>s.status==='ACTIVE'))+select('product','Exact product variant',enabledProducts())+qty()+text('notes','Delivery notes','Demonstration delivery'),'Send to yard')+'</div></section></div>';}
function detail(inPlan=false){const c=state.containers.find(c=>c.id===selected);if(!c)return '';const lines=state.balances.filter(l=>l.container===c.id);const atYardOrSite=state.yards.some(y=>y.id===c.location)||state.sites.some(s=>s.id===c.location);return `<section class="panel selected-detail${inPlan?' in-plan':''}"><div class="row"><h2 class="detail-title">${sprite(c.type==='CAGE'?'spr-cage':'spr-stillage','detail-art')}<span><small>SELECTED ${c.type==='CAGE'?'CAGE':'STILLAGE'}</small>${esc(c.name)}</span></h2>${account.permissions.includes('operations.manage')?`<button class="secondary" data-retire="${c.id}" data-retire-label="${esc(c.name)}" ${lines.length||!atYardOrSite?'disabled':''}>Remove stillage / cage</button>`:''}<button class="secondary" id="close-detail">Close</button></div><p>${esc(name(c.location))} · ${esc(c.condition)} · ${c.envelopeLength} × ${c.envelopeWidth} × ${c.height} mm · tare ${kg(c.tare)}</p>${atYardOrSite&&!inPlan?'<div class="detail-where">'+whereLine(c)+(account.permissions.includes('operations.manage')?turnRow(c)+loadRow(c):'')+'</div>':''}<h3>Contents</h3>${lines.length?lines.map(l=>{const available=l.quantity-l.reserved,canRemove=atYardOrSite&&available>0&&account.permissions.includes('stock.adjust');return `<div class="content-line"><p><strong>${l.quantity} × ${esc(name(l.product_id))}</strong> · ${kg(state.products.find(p=>p.id===l.product_id)?.unitWeight)} each${l.reserved?` · ${l.reserved} reserved`:''}${available>0?` · <span class="badge available">${available} available</span>`:''}</p>${canRemove?`<form id="remove-line-${c.id}-${l.product_id}" class="inline-form remove-line" data-focus-scope="remove:${l.product_id}"><label>Remove<input type="number" name="quantity" value="${available}" min="1" max="${available}" step="1" required></label>${text('reason','Reason','Materials list correction')}<button class="secondary">Remove from this stillage</button></form>`:''}</div>`;}).join(''):'<p>Empty stillage / cage</p>'}${lines.length&&atYardOrSite&&account.permissions.includes('operations.manage')&&account.permissions.includes('stock.adjust')?`<details class="scrap-container"><summary>Remove this stillage anyway</summary><p class="muted">This takes the stillage itself off the yard along with everything still on it — ${lines.reduce((s,l)=>s+l.quantity,0)} piece${lines.reduce((s,l)=>s+l.quantity,0)===1?'':'s'} across ${lines.length} product${lines.length===1?'':'s'}. Use this only when the stillage and its load are gone for good — lost, damaged beyond use or otherwise unrecoverable — not for a quantity mistake (use Remove on the line above instead).</p><form id="scrap-container">${text('reason','Reason')}<button class="secondary">Remove stillage &amp; write off contents</button></form></details>`:''}<p class="muted">Source yard: ${c.sourceYard?esc(name(c.sourceYard)):'—'} · Last placed: ${esc(c.placedAt??'Not moved yet')}</p><form id="move">${select('destination','Move to',[...state.yards,...state.trucks,...state.sites.filter(s=>s.status==='ACTIVE')])}<details><summary>Exact placement (optional)</summary><div class="form-grid">${number('x','X (mm)',Number.isFinite(c.x)?c.x:0,-1000000)}${number('y','Y (mm)',Number.isFinite(c.y)?c.y:0,-1000000)}<label>Rotation<select name="rotation"><option ${(c.rotation??0)===0?'selected':''}>0</option><option ${c.rotation===90?'selected':''}>90</option></select></label><label>Supporting stillage / cage<select name="support"><option value="">Ground level</option>${options(state.containers.filter(o=>o.id!==c.id),'name',c.support??null)}</select></label></div><label class="inline-check"><input name="exact" type="checkbox"> Use these coordinates</label></details><button>Confirm move request</button></form>${account.permissions.includes('operations.manage')?form('condition','Change condition',select('condition','Condition',['SERVICEABLE','DAMAGED','QUARANTINED'].map(id=>({id,name:id})))+text('reason','Condition reason'),'Record condition')+form('container-settings','Configure stillage / cage weight & loaded envelope',number('tare','Tare (g)',c.tare??'')+number('envelopeLength','Loaded length (mm)',c.envelopeLength,1)+number('envelopeWidth','Loaded width (mm)',c.envelopeWidth,1)+text('reason','Configuration reason','Company configured'),'Save frame settings'):''}</section>`;}
function bindScrapContainer(){setOn(document.querySelector('#scrap-container'),'submit',async event=>{event.preventDefault();const node=event.target,data=Object.fromEntries(new FormData(node));if(!confirm('Remove this stillage and write off everything still on it? This cannot be undone.'))return;const button=node.querySelector('button');button.disabled=true;try{const result=await command('scrapContainer',{id:selected,reason:data.reason});notify(result.message);selected=null;await refresh(true);}catch(e){notify(e.message);button.disabled=false;}});}
function bindViews(){
  bind('parking','parking',d=>({id:state.yards[0].id,side:d.side,vehicleLength:Math.round(d.vehicleLength*1000),vehicleWidth:Math.round(d.vehicleWidth*1000),clearance:Math.round(d.clearance*1000)}));
  setOn(document.querySelector('#container [name=type]'),'change',e=>{const f=e.target.form,cage=e.target.value==='CAGE';for(const key of ['length','envelopeLength'])f.elements.namedItem(key).value=cage?1200:2000;for(const key of ['width','envelopeWidth'])f.elements.namedItem(key).value=1000;f.elements.namedItem('name').value=(cage?'C-':'S-')+String(state.containers.length+1).padStart(3,'0');});
  bind('condition','condition',d=>({...d,id:selected}));bind('container-settings','containerSettings',d=>({...d,id:selected}));bind('resources','resources');bind('container','container');bind('opening','opening');bind('truck','truck');bind('site','site');for(const s of state.sites)bind('site-details-'+s.id,'siteDetails',d=>({...d,id:s.id}));if(selected)for(const l of state.balances.filter(l=>l.container===selected))bind('remove-line-'+selected+'-'+l.product_id,'removeStock',d=>({container:selected,product:l.product_id,quantity:d.quantity,reason:d.reason}));bind('request','request');bind('count','count');bind('move','queue',d=>({container:selected,destination:d.destination,...(d.exact?{position:{x:d.x,y:d.y,rotation:Number(d.rotation),support:d.support||null}}:{})}));
  setOn(document.querySelector('#close-detail'),'click',()=>{selected=null;render();});
  bindScrapContainer();
  document.querySelectorAll('#edit-shape,#edit-yard').forEach(b=>b.onclick=()=>{if(state.yards[0])openShapeEditor({kind:'yard',id:state.yards[0].id});});
  document.querySelectorAll('[data-edit-site]').forEach(b=>b.onclick=()=>openShapeEditor({kind:'site',id:b.dataset.editSite}));
  document.querySelectorAll('[data-show-detail]').forEach(b=>b.onclick=()=>document.querySelector('.selected-detail')?.scrollIntoView({block:'start',behavior:'smooth'}));
  setOn(document.querySelector('#planner-turn'),'click',()=>draftTurn(selected));
  setOn(document.querySelector('#stock-search'),'input',e=>stkFilter(e.target.value));
  document.querySelectorAll('[data-component-tab]').forEach(b=>b.onclick=()=>{componentTab=b.dataset.componentTab;render();});
  document.querySelectorAll('[data-stock-tab]').forEach(b=>b.onclick=()=>{stockTab=b.dataset.stockTab;render();});bindPurge();bind('purchase','purchase');bind('remove-stock','removeStock');stkBind();
  setOn(document.querySelector('#add-load-line'),'click',()=>{const box=document.querySelector('#load-lines'),i=box.children.length;box.insertAdjacentHTML('beforeend','<div class="load-line"><label>Product<select name="product'+i+'"><option value="">— none —</option>'+options(enabledProducts())+'</select></label><label>Quantity<input type="number" name="quantity'+i+'" min="0" step="1" value="0"></label></div>');});
  const loadForm=document.querySelector('#load-list');if(loadForm)loadForm.onsubmit=async e=>{e.preventDefault();const fd=new FormData(loadForm),lines=[];for(let i=0;fd.has('product'+i);i++){const product=fd.get('product'+i),quantity=Number(fd.get('quantity'+i));if(product&&quantity>0)lines.push({product,quantity});}if(!lines.length){notify('Add at least one product line with a quantity.');return;}try{await command('createLoadList',{name:fd.get('name'),site:fd.get('site'),notes:fd.get('notes'),lines});notify('Yard list created. Reserve packs to start loading.');await refresh(true);}catch(error){notify(error.message);}};
  document.querySelectorAll('[data-allocate-list]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{const result=await command('allocateLoadList',{id:form.dataset.allocateList,truck:new FormData(form).get('truck')});const short=result.outcome.filter(o=>o.status==='SHORT');notify(short.length?`${result.outcome.length-short.length} line(s) reserved; ${short.length} short: ${short.map(o=>o.reason).join(' ')}`:'Every line reserved. Loading tasks queued.');await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-list]',e=>command('cancelLoadList',{id:e.dataset.cancelList,reason:'Remaining lines cancelled by user'}));
  document.querySelectorAll('[data-allocate]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('allocate',{id:form.dataset.allocate,truck:new FormData(form).get('truck')});await refresh(true);notify('Exact pack plan reserved. Loading tasks queued.');}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-dispatch]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();try{await command('dispatch',{id:form.dataset.dispatch,destination:new FormData(form).get('destination')});await refresh(true);}catch(error){notify(error.message);}});
  document.querySelectorAll('[data-count]').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const fd=new FormData(form),count=state.counts.find(c=>c.id===form.dataset.count);try{await command('observe',{id:count.id,observed:count.lines.map((l,i)=>Number(fd.get(`line${i}`))),reason:fd.get('reason')});await refresh(true);}catch(error){notify(error.message);}});
  action('[data-cancel-request]',e=>command('cancelRequest',{id:e.dataset.cancelRequest,reason:'User cancelled unstarted remainder'}));
  action('[data-approve]',e=>command('approveCount',{id:e.dataset.approve}));action('[data-cancel-count]',e=>command('cancelCount',{id:e.dataset.cancelCount}));action('[data-unload]',e=>command('unload',{id:e.dataset.unload}));action('[data-archive]',e=>command('archive',{id:e.dataset.archive}));
  setOn(document.querySelector('#load-history'),'click',async()=>{try{const rows=await api(`history?after=${historyCursor}&limit=100`);historyCursor=rows.at(-1)?.sequence??historyCursor;document.querySelector('#history').innerHTML=stkHistRows(rows);}catch(e){notify(e.message);}});
  bindOverview();
  ensureTurnInfo();
}

export function catalogueSettings(){return `<section class="panel"><h2>Catalogue & provenance</h2><p>All suggested demo data is synthetic. No manufacturer documents were imported.</p><button id="seed-demo" ${state?.products.length?'disabled':''}>Add synthetic demo catalogue</button></section>${state?purgeButton():''}${account?.permissions.includes('operations.manage')?`<details class="panel"><summary>Import reviewed catalogue batches</summary><p>Choose one or more reviewed JSON batch files (for example the supplier batches in <code>catalogues/verified/</code>). Each file imports atomically: a duplicate or invalid row rejects that whole file. Imports add products only — no stock is created.</p><label>Batch files<input type="file" id="import-batches" accept=".json,application/json" multiple></label><div class="actions"><button type="button" id="import-run">Import selected files</button></div><div id="import-log" class="muted"></div></details>`:''}${state?form('override-product','Configure a product’s operational values',select('product','Product',state.products.filter(p=>!p.retired))+number('unitWeight','Unit weight (g)',5000)+number('packQuantity','Operating full-pack quantity',100,1)+text('reason','Reason','Company-configured DEMO values'),'Save company override'):''}`;}
function bindPurge(){setOn(document.querySelector('#purge-demo'),'click',async()=>{if(!confirm('Remove every demonstration product and all of its stock from this company? Real products and stock are not affected.'))return;try{const r=await command('purgeDemo',{});notify(`Removed ${r.products} demonstration product(s) and ${r.pieces} piece(s).`);if(view==='HOME'||document.querySelector('#seed-demo')){state=await api('state');settings();}else await refresh(true);}catch(e){notify(e.message);}});}
export function bindCatalogue(){bindPurge();setOn(document.querySelector('#import-run'),'click',async()=>{const input=document.querySelector('#import-batches'),log=document.querySelector('#import-log'),files=[...(input?.files??[])].sort((a,b)=>byText(a.name,b.name));if(!files.length){notify('Choose at least one batch file first.');return;}const button=document.querySelector('#import-run');button.disabled=true;let imported=0;log.innerHTML='';for(const file of files){try{const batch=JSON.parse(await file.text());if(!Array.isArray(batch.products))throw new Error('Not a batch file: expected {name, products:[...]}');const result=await command('importCatalogue',{name:batch.name??file.name,products:batch.products});imported+=result.products.length;log.insertAdjacentHTML('beforeend',`<p>✔ ${esc(file.name)} — ${result.products.length} product(s)</p>`);}catch(e){log.insertAdjacentHTML('beforeend',`<p class="error-text">✖ ${esc(file.name)} — ${esc(e.message)}</p>`);}}button.disabled=false;notify(`Imported ${imported} product(s).`);state=await api('state');});setOn(document.querySelector('#seed-demo'),'click',async()=>{try{await command('seed',{});state=await api('state');notify('Synthetic catalogue added. Return to the yard to add stillages, cages and stock.');settings();}catch(e){notify(e.message);}});bind('override-product','override');}

// A crew member's state as a short pill: what they are doing right now.
const crewState=r=>r.task?['load',state.trucks.some(k=>k.id===state.tasks.find(t=>t.id===r.task)?.to)?'Loading a truck':'Moving stock']:r.mountedOn?['drive','Driving a forklift']:r.mountTarget?['walk','Walking to a forklift']:r.walk?['walk',r.walk.job?'Walking to a job':'Walking']:r.job?['job','On a job']:r.workerMode==='HOLD'?['hold','Holding position']:['idle','Idle'],crewBusy=r=>!!(r.task||r.mountedOn||r.mountTarget||r.walk||r.job);
const pill=([k,t])=>'<span class="state-pill '+k+'">'+t+'</span>';
function workerPanel(yard){const workers=state.resources.filter(r=>r.type==='WORKER'&&r.location===yard.id),w=workers.find(r=>r.id===selectedWorker),busy=workers.filter(crewBusy).length;return '<section class="worker-command-panel">'+(w?'':'<div class="crew-head"><div><h2>Your yard crew</h2><p>'+(workers.length?'Select a worker on the plan or below to give orders.':'Configure workers below to add your crew to the yard.')+'</p></div>'+(workers.length?'<span class="crew-count"><b>'+busy+'</b> working &middot; <b>'+(workers.length-busy)+'</b> idle</span>':'')+'</div>')+'<div class="worker-roster">'+workers.map(r=>'<button class="secondary crew-card '+(r.id===selectedWorker?'worker-active':'')+'" data-worker-pick="'+esc(r.id)+'"><span class="crew-avatar">'+sprite(r.task?'spr-worker-busy':'spr-worker')+'</span><span class="crew-name">'+esc(r.name)+'</span>'+pill(crewState(r))+'</button>').join('')+'</div>'+forkliftRoster(yard)+(w?'<button class="worker-close secondary" data-worker-clear aria-label="Deselect worker">&times;</button><div class="worker-orders"><div class="worker-portrait" aria-hidden="true">'+sprite(w.task?'spr-worker-busy':'spr-worker')+'</div><div><div class="eyebrow">SELECTED WORKER</div><h2>'+esc(w.name)+' '+pill(crewState(w))+'</h2><p>'+(w.task?'Assigned to material handling':w.mountedOn?forkliftStatus(w):w.mountTarget?'Walking to '+esc(name(w.mountTarget)):w.walk?(w.walk.job?'Walking to a yard job':'Walking to destination'):w.job?'On a yard job':w.workerMode==='HOLD'?'Holding position':'Ready for automatic work')+'</p>'+(w.board?'<div class="board-line now"><b>NOW</b><span class="text">'+esc(w.board.now.title)+'</span>'+(w.board.now.progress!=null?'<i class="bar" data-progress="'+w.id+'"><span data-style="width:'+w.board.now.progress+'%"></span></i>':'')+'</div>'+(w.board.next?'<div class="board-line"><b>NEXT</b><span class="text">'+esc(w.board.next.title)+'</span></div>':''):'')+(w.workerReason?'<p class="error-text">'+esc(w.workerReason)+'</p>':'')+'</div></div>'+(account.permissions.includes('operations.manage')?'<div class="worker-buttons"><button data-worker-order="MOVE" '+(w.task?'disabled':'')+'>'+(w.mountedOn?'Drive':'Move')+'</button><button class="secondary" data-worker-order="STOP" '+(w.task?'disabled':'')+'>Stop</button><button class="secondary" data-worker-order="HOLD" '+(w.task?'disabled':'')+'>Hold position</button><button class="secondary" data-worker-order="AUTO" '+(w.task||w.mountedOn?'disabled':'')+'>Return to work</button>'+mountControls(w,yard)+'<button class="secondary" data-retire="'+esc(w.id)+'" data-retire-label="worker '+esc(w.name)+'" '+(w.task||w.walk||w.mountedOn||w.mountTarget?'disabled':'')+'>Remove worker</button></div>':'')+(workerMoveMode==='PLACE'?placementPanel():'')+'<p class="worker-help">'+(workerMoveMode==='PLACE'?'Move the pointer to preview. Click to pin, adjust or rotate, then Confirm placement. R rotates; arrow keys nudge.':workerMoveMode?'Click open ground to set the destination.':w.mountedOn?'Right-click ground to drive. Select a stillage, then Pick up. Place load lets you choose its new position.':'Left-click selects. Right-click open ground moves. Hold keeps the worker out of automatic jobs; Return to work makes them available again.')+'</p>':'')+'</section>';}
function forkliftRoster(yard){if(!account.permissions.includes('operations.manage'))return '';const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id);if(!machines.length)return '';return '<div class="forklift-roster">'+machines.map(m=>{const busy=m.task||m.driver||m.claimedBy||m.cargo||m.drive;return '<div class="fork-card"><span class="fork-art">'+sprite(m.cargo?'spr-forklift-load':m.driver?'spr-forklift-driven':'spr-forklift')+'</span><span class="fork-text"><strong>'+esc(m.name)+'</strong>'+pill(m.driver?['drive','Driver: '+esc(name(m.driver))]:m.task?['load','Moving stock']:m.claimedBy?['walk','Worker on the way']:['idle','Free'])+'</span><button type="button" class="secondary" data-retire="'+esc(m.id)+'" data-retire-label="'+esc(m.name)+'" '+(busy?'disabled':'')+'>Remove forklift</button></div>';}).join('')+'</div>';}
function bindWorkers(){
 setOn(document.querySelector('[data-worker-clear]'),'click',()=>{selectedWorker=null;workerMoveMode=false;returnView=null;render();});
 const pick=id=>{if(id!==selectedWorker){workerMoveMode=false;returnView=null;}selectedWorker=id;render();};
 document.querySelectorAll('[data-worker]').forEach(el=>{el.onclick=e=>{e.stopPropagation();pick(el.dataset.worker);};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();pick(el.dataset.worker);}};});
 document.querySelectorAll('[data-worker-pick]').forEach(el=>el.onclick=()=>pick(el.dataset.workerPick));
 document.querySelectorAll('[data-worker-order]').forEach(el=>el.onclick=async()=>{const order=el.dataset.workerOrder,fromRow=!!el.dataset.workerId,id=el.dataset.workerId??selectedWorker;if(order==='MOUNT'){try{const forklift=fromRow?(document.querySelector('[data-mount-select="'+id+'"]')?.value??mountChoice.get(id)):document.querySelector('#mount-forklift').value;await command('workerCommand',{id,order,forklift});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PICKUP'){try{await command('workerCommand',{id,order,container:selected});await refresh(true);}catch(e){notify(e.message);}return;}if(order==='PLACE'){beginPlacement();return;}if(order==='MOVE'){const target=fromRow?(document.querySelector('[data-move-target="'+id+'"]')?.value??moveTarget.get(id)??'plan'):'plan';if(target==='plan'){selectedWorker=id;workerMoveMode='MOVE';if(fromRow){returnView='WORKERS';view='HOME';}render();notify('Click open ground to move, or right-click a destination. Esc cancels.');if(fromRow)document.querySelector('.scene')?.scrollIntoView({block:'start'});return;}try{const w=state.resources.find(r=>r.id===id);await command('workerCommand',{id,order,target,...(w?.mountedOn?{}:{resume:true})});await refresh(true);}catch(e){notify(e.message);}return;}try{await command('workerCommand',{id,order,...(order==='DISMOUNT'&&fromRow?{resume:true}:{})});workerMoveMode=false;await refresh(true);}catch(e){notify(e.message);}});
 document.querySelectorAll('[data-forklift]').forEach(el=>{const choose=()=>{const m=state.resources.find(r=>r.id===el.dataset.forklift);if(m.driver){pick(m.driver);}else{notify(m.claimedBy?'A worker is walking to this forklift.':'Select a worker, then use Mount Forklift.');}};el.onclick=e=>{e.stopPropagation();choose();};el.onkeydown=e=>{if(e.key==='Enter'){choose();}};});
 document.querySelectorAll('[data-plan]').forEach(b=>b.onclick=()=>{const [kind,val]=b.dataset.plan.split(':');if(kind==='zoom'){planView.zoom=Math.min(8,Math.max(0.4,planView.zoom*Number(val)));saveView();applyView();return;}if(kind==='rotate'){planView.rotate=((planView.rotate+Number(val))%360+360)%360;}else if(kind==='tilt'){planView.tilt=!planView.tilt;}else if(kind==='reset'){planView={...DEFAULT_VIEW,tilt:planView.tilt};}saveView();render();});
 const svg=document.querySelector('.scene .yard-svg');if(!svg||!['YARD','HOME'].includes(view))return;
 // A partial patch that kept the plan keeps its listeners; a new plan element gets its own.
 if(!boundSvgs.has(svg)){boundSvgs.add(svg);
 svg.addEventListener('wheel',e=>{e.preventDefault();const factor=e.deltaY<0?1.15:1/1.15,next=Math.min(8,Math.max(0.4,planView.zoom*factor)),k=next/planView.zoom;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const cursor=pt.matrixTransform(svg.getScreenCTM().inverse()),C=planFrame(state.yards[0],planView).screenCentre;planView.pan={x:cursor.x-C.x-k*(cursor.x-C.x-planView.pan.x),y:cursor.y-C.y-k*(cursor.y-C.y-planView.pan.y)};planView.zoom=next;saveView();applyView();},{passive:false});
 let drag=null;svg.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('[data-select],[data-worker],[data-forklift],.plan-turn'))return;const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const at=pt.matrixTransform(svg.getScreenCTM().inverse());drag={x:at.x,y:at.y,pan:{...planView.pan},moved:false,client:{x:e.clientX,y:e.clientY}};});
 svg.addEventListener('pointermove',e=>{if(!drag||!(e.buttons&1))return;if(!drag.moved&&Math.hypot(e.clientX-drag.client.x,e.clientY-drag.client.y)<6)return;drag.moved=true;svg.style.cursor='grabbing';const pt=svg.createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const at=pt.matrixTransform(svg.getScreenCTM().inverse());planView.pan={x:drag.pan.x+(at.x-drag.x),y:drag.pan.y+(at.y-drag.y)};applyView();});
 const endDrag=()=>{if(!drag)return;if(drag.moved){suppressPlanClick=true;saveView();setTimeout(()=>{suppressPlanClick=false;},250);}svg.style.cursor='';drag=null;placeSoon();};svg.addEventListener('pointerup',endDrag);svg.addEventListener('pointerleave',endDrag);
 if(layoutDraft&&['YARD','HOME'].includes(view))bindPlanner(svg,state.yards[0]);
 }
 const move=async e=>{if(!account.permissions.includes('operations.manage'))return;if(workerMoveMode==='JOB_TARGET'){e.preventDefault();if(suppressPlanClick){suppressPlanClick=false;return;}const at=planPoint(svg,e);jobDraft.where={kind:'point',x:Math.round(at.x/500)*500,y:Math.round(at.y/500)*500};jobDraft.whereKey='plan';workerMoveMode=false;view=returnView??'WORKERS';returnView=null;render();notify('Job spot set at '+(jobDraft.where.x/1000).toFixed(1)+', '+(jobDraft.where.y/1000).toFixed(1)+' m.');return;}if(!selectedWorker)return;e.preventDefault();if(suppressPlanClick){suppressPlanClick=false;return;}const at=planPoint(svg,e);try{await command('workerCommand',{id:selectedWorker,order:workerMoveMode==='PLACE'?'PLACE':'MOVE',x:Math.round(at.x-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?1100:250)),y:Math.round(at.y-(workerMoveMode==='PLACE'?0:state.resources.find(r=>r.id===selectedWorker)?.mountedOn?600:250)),...(returnView&&!state.resources.find(r=>r.id===selectedWorker)?.mountedOn?{resume:true}:{})});workerMoveMode=false;if(returnView){view=returnView;returnView=null;}await refresh(true);}catch(error){notify(error.message);}};
 if(workerMoveMode==='PLACE'){bindPlacement(svg);return;}
 svg.oncontextmenu=move;svg.onclick=e=>{if(suppressPlanClick)return;if(workerMoveMode&&!e.target.closest('[data-worker],[data-select]'))move(e);};
 if(workerMoveMode==='MOVE'||workerMoveMode==='JOB_TARGET'){onRenderKey(e=>{if(e.key!=='Escape'||e.target.matches?.('input,select,textarea'))return;workerMoveMode=false;if(returnView){view=returnView;returnView=null;}render();});}
}

function mountControls(w,yard){if(w.mountedOn){const m=state.resources.find(r=>r.id===w.mountedOn),c=state.containers.find(r=>r.id===selected);return '<button data-worker-order="PICKUP" '+(m?.cargo||m?.drive||!c||c.location!==yard.id?'disabled':'')+'>Pick up'+(c?' '+esc(c.name):' selected stillage')+'</button><button data-worker-order="PLACE" '+(!m?.cargo||m?.drive?'disabled':'')+'>Place load</button><button class="secondary" data-worker-order="DISMOUNT" '+(w.task||m?.cargo||m?.drive?'disabled':'')+'>Unmount forklift</button>';}const machines=state.resources.filter(r=>r.type==='FORKLIFT'&&r.location===yard.id&&!r.task&&!r.driver&&!r.claimedBy&&Number.isFinite(r.x));return '<label class="mount-choice">Forklift<select id="mount-forklift" '+(!machines.length?'disabled':'')+'>'+ (machines.length?options(machines):'<option>No free forklift</option>')+'</select></label><button data-worker-order="MOUNT" '+(w.task||w.mountTarget||!machines.length?'disabled':'')+'>Mount forklift</button>';}

function forkliftStatus(w){const m=state.resources.find(r=>r.id===w.mountedOn);return esc(name(w.mountedOn))+' - '+(m?.drive?(m.drive.order==='PICKUP'?'Approaching stillage':m.drive.order==='PLACE'?'Moving to placement':'Driving'):m?.cargo?'Carrying '+esc(m.cargoPreview?.name??name(m.cargo)):'Ready to drive')+(m?.manualReason?'<br><span class="error-text">'+esc(m.manualReason)+'</span>':'');}

function beginPlacement(){const w=state.resources.find(r=>r.id===selectedWorker),m=state.resources.find(r=>r.id===w?.mountedOn);if(!m?.cargoPreview)return;workerMoveMode='PLACE';placementDraft={worker:selectedWorker,cargo:m.cargo,x:Math.round(m.x+2200),y:Math.round(m.y),rotation:m.cargoPreview.rotation??0,snap:100,pinned:false,valid:false,message:'Choose a position on the yard plan.'};render();checkPlacement();}
function placementPanel(){if(!placementDraft)return '';const d=placementDraft;return '<form id="placement-form"><div class="row"><h3>Precise placement</h3><span id="placement-size"></span></div><div class="placement-fields"><label>X (mm)<input name="px" type="number" step="1" min="-1000000" max="1000000" value="'+d.x+'" required></label><label>Y (mm)<input name="py" type="number" step="1" min="-1000000" max="1000000" value="'+d.y+'" required></label><label>Grid snap<select name="snap">'+[1,10,50,100,500,1000].map(n=>'<option value="'+n+'" '+(d.snap===n?'selected':'')+'>'+n+' mm</option>').join('')+'</select></label></div><div class="placement-tools"><button type="button" class="secondary" id="placement-rotate">Rotate 90 deg</button><strong id="placement-angle">'+d.rotation+' deg</strong><button type="button" class="secondary" data-nudge="-1,0" aria-label="Nudge left">Left</button><button type="button" class="secondary" data-nudge="1,0" aria-label="Nudge right">Right</button><button type="button" class="secondary" data-nudge="0,-1" aria-label="Nudge up">Up</button><button type="button" class="secondary" data-nudge="0,1" aria-label="Nudge down">Down</button></div><p id="placement-validation" role="status">'+esc(d.message)+'</p><div class="placement-tools"><button id="placement-confirm" disabled>Confirm placement</button><button type="button" class="secondary" id="placement-reposition">Choose another spot</button><button type="button" class="secondary" id="placement-cancel">Cancel</button></div><p class="muted">X/Y locate the top-left corner of the loaded footprint. Typed coordinates are exact; snapping applies to map clicks. Dashed outline shows forklift access.</p></form>';}
function placementLoad(){const w=state.resources.find(r=>r.id===placementDraft?.worker),m=state.resources.find(r=>r.id===w?.mountedOn);return m?.cargo===placementDraft?.cargo?m.cargoPreview:null;}
function paintPlacement(){const d=placementDraft,svg=document.querySelector('.scene .yard-svg'),c=placementLoad();if(!d||workerMoveMode!=='PLACE'||!svg||!c)return;const width=d.rotation===90?c.envelopeWidth:c.envelopeLength,height=d.rotation===90?c.envelopeLength:c.envelopeWidth,color=d.valid?'#36852e':d.pending?'#ba8730':'#bd4636';svg.querySelector('#placement-ghost')?.remove();const g=document.createElementNS('http://www.w3.org/2000/svg','g');g.id='placement-ghost';g.setAttribute('pointer-events','none');if(Number.isFinite(d.x)&&Number.isFinite(d.y))g.innerHTML='<rect x="'+(d.x-2200)+'" y="'+d.y+'" width="2200" height="1200" fill="none" stroke="'+color+'" stroke-width="45" stroke-dasharray="110 70"/>'+(d.plan?.rotationClearance?'<rect x="'+d.plan.rotationClearance.x+'" y="'+d.plan.rotationClearance.y+'" width="'+d.plan.rotationClearance.w+'" height="'+d.plan.rotationClearance.h+'" fill="none" stroke="#bb872e" stroke-width="30" stroke-dasharray="70 90"/>':'')+'<rect x="'+d.x+'" y="'+d.y+'" width="'+width+'" height="'+height+'" fill="'+color+'" fill-opacity=".3" stroke="'+color+'" stroke-width="60"/><path d="M '+(d.x-170)+' '+d.y+' H '+(d.x+170)+' M '+d.x+' '+(d.y-170)+' V '+(d.y+170)+'" stroke="'+color+'" stroke-width="35"/><text x="'+d.x+'" y="'+(d.y-260)+'" font-size="230" fill="'+color+'" stroke="#f8ffeb" stroke-width="12" paint-order="stroke">'+width+' x '+height+' mm / '+d.rotation+' deg</text>';(svg.querySelector('#plan')??svg).append(g);const status=document.querySelector('#placement-validation');if(status){status.textContent=d.message;status.className=d.valid?'placement-valid':d.pending?'':'error-text';}const confirm=document.querySelector('#placement-confirm');if(confirm)confirm.disabled=!d.valid||d.pending;document.querySelector('#placement-angle')?.replaceChildren(document.createTextNode(d.rotation+' deg'));document.querySelector('#placement-size')?.replaceChildren(document.createTextNode(width+' x '+height+' mm'));}
async function checkPlacement(){clearTimeout(placementTimer);const d=placementDraft,seq=++placementSequence;if(!d||workerMoveMode!=='PLACE')return;d.valid=false;d.pending=true;d.plan=null;d.message='Checking footprint, access and rotation clearance...';paintPlacement();try{const plan=await api('placement-preview',{id:d.worker,container:d.cargo,x:d.x,y:d.y,rotation:d.rotation});if(seq!==placementSequence||d!==placementDraft||workerMoveMode!=='PLACE')return;d.plan=plan;d.valid=true;d.message='Position and route clear. Confirm to place.';}catch(e){if(seq!==placementSequence||d!==placementDraft)return;d.message=e.message;}d.pending=false;paintPlacement();}
function editPlacement(x,y){const d=placementDraft;if(!d)return;placementSequence++;d.x=x;d.y=y;d.valid=false;d.pending=true;d.plan=null;d.message='Checking position...';const f=document.querySelector('#placement-form');if(f){f.elements.namedItem('px').value=Number.isFinite(x)?x:'';f.elements.namedItem('py').value=Number.isFinite(y)?y:'';}paintPlacement();clearTimeout(placementTimer);placementTimer=setTimeout(checkPlacement,180);}
function bindPlacement(svg){const d=placementDraft,f=document.querySelector('#placement-form');if(!d||!f)return;paintPlacement();const rotate=()=>{d.rotation=d.rotation===0?90:0;editPlacement(d.x,d.y);};const nudge=(x,y)=>{d.pinned=true;editPlacement(d.x+x*d.snap,d.y+y*d.snap);};const pick=(e,pin)=>{const at=planPoint(svg,e);if(pin)d.pinned=true;editPlacement(Math.round(at.x/d.snap)*d.snap,Math.round(at.y/d.snap)*d.snap);};svg.onpointermove=e=>{if(!d.pinned&&e.pointerType!=='touch')pick(e,false);};svg.addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();pick(e,true);},true);svg.oncontextmenu=e=>{e.preventDefault();pick(e,true);};for(const key of ['px','py'])f.elements.namedItem(key).oninput=()=>{d.pinned=true;editPlacement(f.elements.namedItem('px').valueAsNumber,f.elements.namedItem('py').valueAsNumber);};f.elements.namedItem('snap').onchange=e=>{d.snap=Number(e.target.value);};document.querySelector('#placement-rotate').onclick=rotate;document.querySelectorAll('[data-nudge]').forEach(b=>b.onclick=()=>nudge(...b.dataset.nudge.split(',').map(Number)));document.querySelector('#placement-reposition').onclick=()=>{d.pinned=false;notify('Move over the yard and click to pin a new position.');};const cancel=()=>{placementSequence++;clearTimeout(placementTimer);placementDraft=null;workerMoveMode=false;render();};document.querySelector('#placement-cancel').onclick=cancel;onRenderKey(e=>{if(workerMoveMode!=='PLACE'||e.target.matches?.('input,select,textarea'))return;if(e.key.toLowerCase()==='r'){e.preventDefault();rotate();}const keys={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowUp:[0,-1],ArrowDown:[0,1]};if(keys[e.key]){e.preventDefault();nudge(...keys[e.key]);}if(e.key==='Escape')cancel();});f.onsubmit=async e=>{e.preventDefault();if(!d.valid||d.pending)return;document.querySelector('#placement-confirm').disabled=true;try{await command('workerCommand',{id:d.worker,container:d.cargo,order:'PLACE',x:d.x,y:d.y,rotation:d.rotation});placementDraft=null;workerMoveMode=false;placementSequence++;await refresh(true);notify('Exact placement confirmed. Forklift moving.');}catch(error){d.valid=false;d.message=error.message;paintPlacement();}};}

// ----- Turning a stillage: the plan overlay button, the selection bar under each plan, the detail row, the ghost and the R key. -----
const m1=v=>(v/1000).toFixed(1);
const listWords=names=>names.length<2?names.join(''):names.slice(0,-1).join(', ')+' and '+names.at(-1);
const footOf=(o,p=o)=>{const L=o.envelopeLength??o.length??2000,W=o.envelopeWidth??o.width??1000,r=(p.rotation??0)===90;return {x:p.x,y:p.y,w:r?W:L,h:r?L:W};};
const locOf=id=>state.yards.find(y=>y.id===id)??state.sites.find(s=>s.id===id)??null;
const storedAt=id=>{const c=state.containers.find(o=>o.id===id);return c&&locOf(c.location)?c:null;};
const machineWord=c=>locOf(c.location)?.kind==='site'?'crane':'forklift';
const siteViewOf=()=>({...DEFAULT_VIEW,tilt:planView.tilt});
const planOpts=extra=>({balances:state.balances,products:state.products,cornerNumbers:true,pulse:Date.now()<pulse.until?pulse.ids:null,...extra});
const planHead=(yard,suffix)=>'<div class="plan-head-actions"><span>'+dims(yard)+suffix+'</span>'+(isOps()?'<button type="button" class="secondary" id="edit-shape">Change yard shape &amp; size</button>':'')+'</div>';
