function orientText(c,loc){const L=c.envelopeLength,W=c.envelopeWidth;if(L===W)return 'square';const horiz=c.rotation===90?W>L:L>W,d=horiz?{x:1,y:0}:{x:0,y:1},pts=normalise(loc.points??[]);const side=pts.length>2?ringSides(pts).find(s=>s.length>0&&Math.abs((pts[s.to].x-pts[s.from].x)*d.y-(pts[s.to].y-pts[s.from].y)*d.x)/s.length<0.0175):null;return side?'long side along side '+(side.i+1)+' ('+m1(side.length)+' m)':horiz?'long side across the plan':'long side up and down the plan';}
